package com.cdac.cssip.task.entity;import jakarta.persistence.*;import lombok.*;import java.time.*;@Entity @Table(name="task_assignments",uniqueConstraints=@UniqueConstraint(columnNames={"task_id","student_id"}))@Getter @Setter @NoArgsConstructor @AllArgsConstructor @Builder public class TaskAssignment{@Id @GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@Column(name="task_id",nullable=false)private Long taskId;@Column(name="student_id",nullable=false)private Long studentId;@Column(nullable=false)private String status;private LocalDateTime completedAt;}
